"""Score months (not counted / set score), Convert, Help Desk admin-only, Feedback, folded admin tabs, DARRIK.html."""
import os
from harness import app_session, Check, run, SHOTS, APP
async def main():
    c = Check('months · convert · help desk · feedback')
    c('app file is DARRIK.html', os.path.isfile(os.path.join(APP, 'DARRIK.html')))
    async with app_session() as s:
        pg = s.page; J = s.js
        y = await J("App.year")
        # ---------- folded tabs
        t = await s.go('#/admin/people', 600)
        c('Manager leave is on People', 'Manager leave & delegation' in t and await pg.locator('.tabs a, .adm-tabs a').filter(has_text='Manager leave').count() == 0)
        t = await s.go('#/admin/scoring', 600)
        c('Month locks + Months + what-if on Scoring', 'Month locks' in t and 'Months — ' in t and 'Scoring what-if' in t)
        t = await s.go('#/admin/months', 500); c('old link still works', 'Month locks' in t)
        # ---------- months: give Yousef some work in month 1 so he has a score
        await J(f"Store.saveMany([{{c:'shadow', id:'sm-s1', analyst:'yousef', team:'apps', date:'{y}-01-10', taskType:(L('taskTypes')()[0]||'Support'), subject:'x', minutes:600}}, {{c:'shadow', id:'sm-s2', analyst:'yousef', team:'apps', date:'{y}-02-10', taskType:(L('taskTypes')()[0]||'Support'), subject:'y', minutes:600}}])"); await J("Calc.invalidate()")
        a1 = await J(f"(Calc.score({y}, 'yousef', 1) || {{}}).score")
        c('January has a calculated score', a1 is not None)
        await s.go('#/admin/scoring', 600)
        # whole-team: January not counted
        await pg.click('[data-smm="1"]'); await pg.wait_for_selector('#smf'); await pg.check('#smf [name=kind][value=skip]'); await pg.fill('#smf [name=note]', 'Go-live month'); await pg.click('.modal [data-ok]'); await pg.wait_for_timeout(500)
        c('January not counted for the team', await J(f"Calc.score({y}, 'yousef', 1)") is None and await J(f"Calc.monthMark({y}, 'layla', 1).kind") == 'skip')
        # one person: February set score
        await pg.click('[data-smc="yousef|2"]'); await pg.wait_for_selector('#smf'); await pg.check('#smf [name=kind][value=set]'); await pg.fill('#smf [name=score]', '91'); await pg.fill('#smf [name=note]', 'new site activation'); await pg.click('.modal [data-ok]'); await pg.wait_for_timeout(500)
        c('February set to 91 for Yousef', await J(f"Calc.score({y}, 'yousef', 2).score") == 91 and await J(f"Calc.score({y}, 'yousef', 2).set"))
        c('yearly average skips January and uses 91', await J(f"Calc.heatmap({y}).rows.find(r => r.m.id === 'yousef').cells[0]") is None)
        # person override wins: Yousef counts in January after all
        await pg.click('[data-smc="yousef|1"]'); await pg.wait_for_selector('#smf'); await pg.check('#smf [name=kind][value=set]'); await pg.fill('#smf [name=score]', '80'); await pg.fill('#smf [name=note]', 'Covered go-live'); await pg.click('.modal [data-ok]'); await pg.wait_for_timeout(400)
        c("a person's mark wins over the team's", await J(f"Calc.score({y}, 'yousef', 1).score") == 80)
        t = await s.go('#/dashboard', 600); c('heatmap marks ⊘ and ✎', '⊘' in t and '✎' in t)
        await pg.screenshot(path=f'{SHOTS}/score_months.png', full_page=True)
        await s.sign_in_as('apps-mgr'); await J(f"Store.save(Object.assign({{}}, Store.get('settings-scoremonths-apps'), {{months: {{}}}}))"); await pg.wait_for_timeout(200)
        c('…manager cannot', await J(f"Calc.monthMark({y}, 'layla', 1).kind") == 'skip')
        # ---------- convert
        await s.sign_in_as('yousef')
        await J("Store.save({c:'shadow', id:'cv-s1', analyst:'yousef', team:'apps', date:U.todayStr(), taskType:(L('taskTypes')()[0]||'Support'), subject:'Built order set report', minutes:90})"); await pg.wait_for_timeout(200)
        await J("UI.editRecord('shadow', Store.get('cv-s1'))"); await pg.wait_for_selector('[data-convert]')
        await pg.click('[data-convert]'); await pg.wait_for_selector('[data-cvto]')
        c('analyst: To Do option disabled', await pg.is_disabled('[data-cvto="todo"]') and not await pg.is_disabled('[data-cvto="quickwin"]'))
        await pg.click('[data-cvto="quickwin"]'); await pg.wait_for_selector('#recform')
        c('quick win form filled in', await pg.input_value('#recform [name=subject]') == 'Built order set report')
        await pg.click('[data-save]'); await pg.wait_for_timeout(400)
        c('module is required', await pg.locator('#recform').count() == 1 and await J("!!Store.get('cv-s1')"))
        await pg.fill('#recform [name=module]', 'Orders'); await pg.click('[data-save]'); await pg.wait_for_timeout(600)
        c('original removed from Shadow work', await J("Store.get('cv-s1')") is None)
        qw = await J("Store.all('quickwin', '*').find(q => q.convertedFrom && q.convertedFrom.id === 'cv-s1')")
        c('new quick win says converted from Shadow work', qw and qw['convertedFrom']['c'] == 'shadow')
        t = await s.go('#/quickwins', 500); c('list shows ⇄ Shadow work', '⇄ Shadow work' in t)
        await J(f"UI.editRecord('quickwin', Store.get('{qw['id']}'))"); await pg.wait_for_selector('#recform')
        c('form says Converted from Shadow work', 'Converted from Shadow work' in await pg.inner_text('.modal'))
        await pg.click('[data-cvundo]'); await pg.wait_for_timeout(500)
        c('undo brings the shadow work back', await J("!!Store.get('cv-s1')") and await J(f"Store.get('{qw['id']}')") is None)
        # manager converts a To Do to shadow work
        await s.sign_in_as('apps-mgr')
        await J("Store.save({c:'todo', id:'cv-t1', analyst:'yousef', team:'apps', task:'Check lab mapping', assigned:U.todayStr(), duration:2, status:'In Progress'})"); await pg.wait_for_timeout(200)
        await J("UI.editRecord('todo', Store.get('cv-t1'))"); await pg.wait_for_selector('[data-convert]'); await pg.click('[data-convert]'); await pg.wait_for_selector('[data-cvto]')
        await pg.click('[data-cvto="shadow"]'); await pg.wait_for_selector('#recform')
        c('shadow form asks for the task type', await pg.locator('#recform [name=taskType]').count() == 1)
        await pg.click('[data-save]'); await pg.wait_for_timeout(300)
        c('shadow work needs a source', await pg.locator('#recform').count() == 1)
        await J("(() => { const el = document.querySelector('#recform [name=source]'); const o = [...el.options].find(o => o.value); el.value = o.value; })()")
        await J("(() => { const el = document.querySelector('#recform [name=taskType]'); const o = [...(el.options || [])].find(o => o.value); if (o) el.value = o.value; else el.value = 'Support'; el.dispatchEvent(new Event('change')); })()")
        await pg.click('[data-save]'); await pg.wait_for_timeout(600)
        c('manager: To Do → Shadow work', await J("Store.get('cv-t1')") is None and await J("Store.all('shadow', '*').some(x => x.convertedFrom && x.convertedFrom.id === 'cv-t1' && x.subject === 'Check lab mapping' && x.analyst === 'yousef')"))
        # ---------- help desk: admin only
        t = await s.go('#/helpdesk/requests', 500)
        c('manager: no Add manually', 'Add manually' not in t)
        await J("Store.save({c:'helpdesk', reqId: 999001, subject:'manual', team:'apps'})"); await pg.wait_for_timeout(200)
        c('manager cannot add one by hand', not await J("Store.all('helpdesk', '*').some(r => r.reqId === 999001)"))
        await s.sign_in_as('adam'); t = await s.go('#/helpdesk/requests', 500)
        c('admin: Add manually', 'Add manually' in t)
        await J("Store.save({c:'helpdesk', id:'hd-man1', reqId: 999002, subject:'manual', team:'apps'})"); await pg.wait_for_timeout(200)
        c('admin can add', await J("!!Store.get('hd-man1')"))
        await s.sign_in_as('apps-mgr'); await J("Store.save(Object.assign({}, Store.get('hd-man1'), {_del: true}))"); await pg.wait_for_timeout(200)
        c('manager cannot delete', await J("!!Store.get('hd-man1')"))
        # ---------- feedback
        await s.sign_in_as('layla'); c('Feedback in the menu', await pg.locator('nav [data-nav="feedback"]').count() == 1)
        c('no feedback button on other pages', await pg.locator('header.top :text("Feedback")').count() == 0)
        await s.go('#/attendance', 300); await s.go('#/feedback', 400)
        await pg.click('#fbnew'); await pg.wait_for_selector('#fbf')
        await pg.fill('#fbf [name=title]', 'Attendance page does not save permission hours'); await pg.fill('#fbf [name=details]', 'I typed 2 hours and pressed save'); await pg.select_option('#fbf [name=urgency]', 'blocking')
        await pg.click('.modal [data-ok]'); await pg.wait_for_timeout(400)
        fb = await J("FB.all()[0]")
        c('sent with page and version', fb and fb['from'] == 'layla' and fb['status'] == 'New' and fb['page'] == 'attendance' and fb['ver'])
        await J("Store.save(Object.assign({}, FB.all()[0], {status: 'Done', reply: 'self-approved'}))"); await pg.wait_for_timeout(200)
        c('sender cannot set status / reply', await J("FB.all()[0].status") == 'New')
        await s.sign_in_as('yousef'); await s.go('#/feedback', 300); await pg.click('[data-fbtab="all"]'); await pg.wait_for_timeout(300)
        await pg.click(f'[data-fbvote="{fb["id"]}"]'); await pg.wait_for_timeout(300)
        c('👍 Me too', await J(f"FB.votes('{fb['id']}').length") == 1)
        await s.sign_in_as('adam', 'analyst'); c('red dot counts new feedback', 'new feedback' in (await pg.get_attribute('#modebtn', 'title') or ''))
        await s.sign_in_as('adam'); t = await s.go('#/admin/feedback', 500)
        c('Admin → Feedback lists it', 'Attendance page does not save permission hours' in t and 'blocking' in t)
        await pg.click(f'[data-fbadm="{fb["id"]}"]'); await pg.wait_for_selector('#fba')
        await pg.select_option('#fba [name=status]', 'Planned'); await pg.select_option('#fba [name=priority]', 'High'); await pg.fill('#fba [name=reply]', 'Thanks — fixing it this week'); await pg.click('.modal [data-ok]'); await pg.wait_for_timeout(400)
        c('admin answered', await J(f"Store.get('{fb['id']}').status") == 'Planned' and await J(f"Store.get('{fb['id']}').reply") == 'Thanks — fixing it this week')
        await pg.screenshot(path=f'{SHOTS}/admin_feedback.png', full_page=True)
        await s.sign_in_as('layla'); t = await s.go('#/home', 500)
        c('sender sees the answer on My Day', 'answered your feedback' in t)
        t = await s.go('#/feedback', 400); c('…and on Feedback', 'Thanks — fixing it this week' in t and 'Planned' in t)
        t = await s.go('#/home', 400); c('notice gone once seen', 'answered your feedback' not in t)
        c.done(s)
run(main())
